            {'.', '6', '.', '.', '.', '.', '2', '8', '.'},
            {'.', '.', '.', '4', '1', '9', '.', '.', '5'},
            {'.', '.', '.', '.', '8', '.', '.', '7', '9'}
        };

        assertFalse(solution.isValidSudoku(board));
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldRejectDuplicateInRow() {

        Solution solution = new Solution();

        char[][] board = {
            {'5', '5', '.', '.', '.', '.', '.', '.', '.'},
            {'.', '.', '.', '.', '.', '.', '.', '.', '.'},
